#!/usr/bin/env node
/**
 * Regenerates `src/utils/countryNames.ts`.
 *
 * Run from `threadly-mobile/`:
 *
 *     node scripts/generate-phone-country-names.js
 *
 * The region list comes from `libphonenumber-js` — the same metadata the phone
 * field validates against, so the table and the validator can never disagree
 * about which regions exist — and the names come from Node's
 * `Intl.DisplayNames`. Node has full ICU; Hermes does not, which is the whole
 * reason this is generated ahead of time rather than resolved on device. See
 * the header of the generated file.
 */
const fs = require('fs');
const path = require('path');
const { getCountries } = require('libphonenumber-js');

if (typeof Intl.DisplayNames !== 'function') {
  console.error('This Node build has no Intl.DisplayNames — cannot generate names.');
  process.exit(1);
}

const display = new Intl.DisplayNames(['en'], { type: 'region' });
const rows = getCountries()
  .map((iso2) => {
    let name = iso2;
    try {
      name = display.of(iso2) || iso2;
    } catch {
      /* An unnamed region keeps its code rather than vanishing. */
    }
    return { iso2, name };
  })
  .sort((a, b) => a.iso2.localeCompare(b.iso2));

const unnamed = rows.filter((row) => row.name === row.iso2);
if (unnamed.length > rows.length / 10) {
  console.error(
    `Refusing to write: ${unnamed.length} of ${rows.length} regions resolved to their bare code.`,
  );
  process.exit(1);
}

const header = `/**
 * ISO-3166 alpha-2 -> English country name, bundled.
 *
 * GENERATED by \`scripts/generate-phone-country-names.js\` — do not hand-edit.
 *
 * It is a static table on purpose:
 *
 * 1. **Hermes has no \`Intl.DisplayNames\`.** Its Intl surface is Collator,
 *    DateTimeFormat, NumberFormat and \`getCanonicalLocales\`, and nothing else.
 *    Web resolves these names at runtime
 *    (\`fthreadly/src/utils/phoneCountries.ts\`) and falls back to the bare code
 *    when the API is missing; on this platform that fallback is not an edge
 *    case, it is EVERY row, and a picker listing "AD, AE, AF…" is not a country
 *    picker. Same class of defect as the money note: Hermes ships a cut-down
 *    ICU, so identical code renders differently on device than in a browser.
 * 2. Phone entry must work with no network. The country list used by the
 *    LOCATION cascade comes from a third-party API; the phone field's names and
 *    dial codes must not depend on that API being up.
 */
export const COUNTRY_NAMES_BY_ISO2: Record<string, string> = {
`;

// JSON.stringify does the quoting and escaping, so this generator never has to
// hand-roll an escape table for names like "Cote d'Ivoire".
const body = rows.map((row) => `  ${row.iso2}: ${JSON.stringify(row.name)},`).join('\n');

const out = `${header}${body}
};

export default COUNTRY_NAMES_BY_ISO2;
`;

const target = path.join(__dirname, '..', 'src', 'utils', 'countryNames.ts');
fs.writeFileSync(target, out, 'utf8');
console.log(`wrote ${rows.length} countries to ${path.relative(process.cwd(), target)}`);
